import{join}from"node:path";import{pathExists}from"#setup/scaffold/files.js";import{select}from"#setup/ask.js";const WEB_CHAT_FRAMEWORK_LABELS={next:`Next.js`,tanstack:`TanStack Start`},WEB_FRAMEWORK_QUESTION=select({key:`web-framework`,message:`Which framework should Web Chat use?`,options:[{id:`next`,label:WEB_CHAT_FRAMEWORK_LABELS.next,hint:`(Recommended) Supports Sign in with Vercel.`,value:`next`},{id:`tanstack`,label:WEB_CHAT_FRAMEWORK_LABELS.tanstack,hint:`A Vite app built with TanStack Router.`,value:`tanstack`}],recommended:`next`,required:!0}),HOST_CONFIG_FILES={next:[`next.config.ts`,`next.config.mjs`,`next.config.js`],tanstack:[`vite.config.ts`,`vite.config.mjs`,`vite.config.js`]};async function hasAny(e,t,n){for(let r of t)if(await n(join(e,r)))return!0;return!1}async function detectWebChatFramework(e,t=pathExists){let[n,r]=await Promise.all([hasAny(e,HOST_CONFIG_FILES.next,t),hasAny(e,HOST_CONFIG_FILES.tanstack,t)]);if(n&&r)throw Error(`${e} contains both a Next.js and a Vite config. Remove the app you no longer use, then retry.`);return n?`next`:r?`tanstack`:void 0}export{WEB_CHAT_FRAMEWORK_LABELS,WEB_FRAMEWORK_QUESTION,detectWebChatFramework};